const company = $('Get Company Details').item.json;
const items = $input.all();
const pitches = items.map(it => it.json);

const baseUrl = 'https://canchas-mino.vercel.app';

let pitchesText = '';
if (pitches.length === 0) {
  pitchesText = 'No hay canchas registradas en este complejo.';
} else {
  pitchesText = pitches.map((p, idx) => {
    return `${idx + 1}. ID: ${p.id} | Nombre: "${p.name}" | Tipo: ${p.type || 'Fútbol'} | Superficie: ${p.surface || 'Sintética'} | Link Reservar: ${baseUrl}/cancha/${p.id}`;
  }).join('\n');
}

return [{
  json: {
    companyId: company.id,
    companyName: company.name,
    totalPitches: pitches.length,
    pitchesListText: pitchesText,
    pitchesData: pitches,
    baseUrl: baseUrl
  }
}];

